script:
(function () {
  'use strict';
  // Breakeven (cost-volume-profit) analysis for a single product.
  //   Contribution margin per unit CM = price - variable cost; CM ratio = CM / price.
  //   Breakeven units = fixed costs / CM; breakeven sales = fixed costs / CM ratio.
  //   Units for a target profit = (fixed costs + target profit) / CM; sales = (fixed + target) / CM ratio.
  //   At expected sales Q: profit = Q * CM - fixed; margin of safety = Q - breakeven units (also in
  //   dollars and as % of expected sales); degree of operating leverage = Q * CM / profit (profit > 0).
  // Verified in Node (scratchpad tests/b2biz): fixed $50,000, price $5, variable $2.50, 25,000 units ->
  //   breakeven 20,000 units / $100,000, profit $12,500, margin of safety 5,000 units (20%) (matches a
  //   published breakeven calculator's default result); fixed $60,000, price $25, variable $15, 8,000
  //   units, target $20,000 -> CM ratio 40%, breakeven 6,000 units / $150,000, target 8,000 units /
  //   $200,000, margin of safety 25%, operating leverage 4.00 (hand-checked). Price at or below variable
  //   cost, blank, zero price and negative input show a message, never NaN/Infinity.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var units = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
  var dec = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var one = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

  // --- calc ---
  function breakeven(fixed, price, variable, expected, target) {
    var cm = price - variable;
    var r = { cm: cm, cmRatio: price > 0 ? cm / price : null, possible: cm > 0 };
    if (!r.possible) return r;
    r.beUnits = fixed / cm;
    r.beSales = r.beUnits * price;
    r.targetUnits = (fixed + target) / cm;
    r.targetSales = r.targetUnits * price;
    r.revenue = expected * price;
    r.variableTotal = expected * variable;
    r.totalCost = fixed + r.variableTotal;
    r.profit = expected * cm - fixed;
    r.mosUnits = expected - r.beUnits;
    r.mosSales = r.mosUnits * price;
    r.mosPct = expected > 0 ? r.mosUnits / expected : null;
    r.dol = r.profit > 0 ? expected * cm / r.profit : null;
    return r;
  }

  function volumes(beUnits, expected) {
    var base = beUnits > 0 ? beUnits : (expected > 0 ? expected : 1000);
    var list = [0, 0.25, 0.5, 0.75, 1, 1.25, 1.5, 2].map(function (f) { return Math.round(base * f); });
    if (expected > 0) list.push(Math.round(expected));
    list.sort(function (a, b) { return a - b; });
    return list.filter(function (v, i) { return i === 0 || v !== list[i - 1]; });
  }
  // --- end calc ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  var OUT = ['beUnits', 'beSales', 'beCm', 'beCmRatio', 'beTargetUnits', 'beTargetSales', 'beRevenue',
             'beVarTotal', 'beTotalCost', 'beProfit', 'beMosUnits', 'beMosSales', 'beMosPct', 'beDol'];

  function clearResults() {
    OUT.forEach(function (id) { setText(id, '–'); });
    el('beTable').textContent = '';
  }

  function wholeUnits(x) { return units.format(Math.max(0, Math.ceil(x - 1e-9))) + ' units'; }

  function update() {
    var fixed = read('beFixed'), price = read('bePrice'), variable = read('beVariable'),
        expected = read('beExpected', true), target = read('beTarget', true);
    var msg = '';
    if (isNaN(fixed) || fixed < 0) msg = 'Enter fixed costs of $0 or more.';
    else if (isNaN(price) || price <= 0) msg = 'Enter a selling price per unit greater than $0.';
    else if (isNaN(variable) || variable < 0) msg = 'Enter a variable cost per unit of $0 or more.';
    else if (isNaN(expected) || expected < 0) msg = 'Expected unit sales cannot be negative.';
    else if (isNaN(target) || target < 0) msg = 'Target profit cannot be negative.';
    var error = el('beError');
    error.hidden = !msg;
    error.textContent = msg;
    var warn = el('beWarning');
    warn.hidden = true;
    if (msg) { clearResults(); return; }

    var r = breakeven(fixed, price, variable, expected, target);
    setText('beCm', money.format(r.cm));
    setText('beCmRatio', one.format(r.cmRatio * 100) + '%');
    if (!r.possible) {
      OUT.forEach(function (id) { if (id !== 'beCm' && id !== 'beCmRatio') setText(id, 'n/a'); });
      el('beTable').textContent = '';
      warn.hidden = false;
      setText('beWarningText', 'The selling price does not cover the variable cost of each unit, so every extra sale adds to the loss and there is no breakeven point. Raise the price or lower the variable cost.');
      return;
    }
    setText('beUnits', wholeUnits(r.beUnits));
    setText('beSales', money0.format(r.beSales));
    setText('beTargetUnits', wholeUnits(r.targetUnits));
    setText('beTargetSales', money0.format(r.targetSales));
    setText('beRevenue', money0.format(r.revenue));
    setText('beVarTotal', money0.format(r.variableTotal));
    setText('beTotalCost', money0.format(r.totalCost));
    setText('beProfit', money0.format(r.profit));
    setText('beMosUnits', units.format(Math.round(r.mosUnits)) + ' units');
    setText('beMosSales', money0.format(r.mosSales));
    setText('beMosPct', r.mosPct === null ? 'n/a' : one.format(r.mosPct * 100) + '%');
    setText('beDol', r.dol === null ? 'n/a' : dec.format(r.dol));
    if (expected > 0 && r.mosUnits < 0) {
      warn.hidden = false;
      setText('beWarningText', 'Expected sales are below the breakeven point, so the plan shows a loss. The negative margin of safety is how many more units you would need to sell to break even.');
    }

    var body = el('beTable');
    body.textContent = '';
    volumes(r.beUnits, expected).forEach(function (q) {
      var tr = document.createElement('tr');
      var cells = [units.format(q), money0.format(q * price), money0.format(q * variable), money0.format(fixed),
                   money0.format(fixed + q * variable), money0.format(q * r.cm - fixed)];
      cells.forEach(function (text) {
        var td = document.createElement('td');
        td.textContent = text;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('beForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
